// Save to database using Sequelize bulkCreate with upsert on symbol conflict
const dbResult = await Instrument.bulkCreate(instruments, {
  updateOnDuplicate: ['name', 'type', 'market', 'category', 'status', 'updated_at'],
  validate: true,
});

// File-system backup (best-effort)
try {
  const fs = require('fs');
  const path = require('path');
  const dataDir = path.join(__dirname, '../../data');

  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  const filePath = path.join(dataDir, 'instruments.json');
  fs.writeFileSync(filePath, JSON.stringify({
    data: instruments,
    timestamp: Date.now(),
    count: instruments.length
  }, null, 2));
} catch (fsErr) {
  console.warn('⚠️ File backup write failed:', fsErr.message);
}

console.log(`✅ 成功持久化 ${instruments.length} 个标的到数据库 (db: ${dbResult.length} rows)`);

res.json({
  success: true,
  data: {
    count: instruments.length,
    dbRows: dbResult.length
  },
  message: '标的列表持久化成功'
});
